import{_ as r,o,c as a,a7 as e}from"./chunks/framework.Bn19FVGY.js";const i="/ruidu-docs/images/orbitcontrol/user-guide/route-graph-page-main.png",l="/ruidu-docs/images/orbitcontrol/user-guide/route-graph-panel-inherit.gif",m=JSON.parse('{"title":"路网","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/route-graph.md","filePath":"orbitcontrol/user-guide/route-graph.md"}'),s={name:"orbitcontrol/user-guide/route-graph.md"};function n(d,t,h,c,p,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="路网" tabindex="-1">路网 <a class="header-anchor" href="#路网" aria-label="Permalink to &quot;路网&quot;">​</a></h1><p>「路网」描述设备在地图上的可行驶路径：由<strong>节点</strong>（路经点、充电点、电梯点、停靠点）、<strong>边</strong>（路径连线）和<strong>区域</strong>组成。建好路网后：</p><ul><li><a href="./missions.html">任务</a> 编辑时可点击路网节点直接取点</li><li><a href="./live-control.html">设备控制</a> 页可点击节点让设备前往</li><li>设备导航沿路网行驶，路线更可控</li></ul><p>路网归属地图，每张地图维护自己的路网。</p><h2 id="页面布局" tabindex="-1">页面布局 <a class="header-anchor" href="#页面布局" aria-label="Permalink to &quot;页面布局&quot;">​</a></h2><p>顶部工具栏从左到右：站点选择、地图选择、<strong>继承</strong>、<strong>录制</strong>、<strong>显示设备</strong>、版本指示、<strong>保存</strong>。</p><p><img src="'+i+'" alt=""></p><ul><li><strong>版本指示</strong>：显示已保存的版本号；地图尚无路网时提示「该地图尚无路网」</li><li><strong>未保存</strong>：编辑后有未保存的修改时出现，点击「保存」提交为新版本（版本号 +1）</li></ul><h2 id="手动编辑" tabindex="-1">手动编辑 <a class="header-anchor" href="#手动编辑" aria-label="Permalink to &quot;手动编辑&quot;">​</a></h2><h3 id="放置节点" tabindex="-1">放置节点 <a class="header-anchor" href="#放置节点" aria-label="Permalink to &quot;放置节点&quot;">​</a></h3><p>进入加点模式后点击地图放置节点，节点分四类：</p><table tabindex="0"><thead><tr><th>节点类型</th><th>说明</th></tr></thead><tbody><tr><td>路经点</td><td>路径上的普通经过点（显示序号）</td></tr><tr><td>充电点</td><td>充电桩位置</td></tr><tr><td>电梯点</td><td>电梯位置</td></tr><tr><td>停靠点</td><td>设备停靠/待命位置</td></tr></tbody></table><p>选中节点可修改类型和朝向。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>开启「显示设备」后，地图上显示在线设备；编辑中点击设备图标，可直接取设备当前位置和朝向作为节点位置。</p></div><h3 id="连线路径" tabindex="-1">连线路径 <a class="header-anchor" href="#连线路径" aria-label="Permalink to &quot;连线路径&quot;">​</a></h3><p>进入连线路模式后依次点击地图，生成<strong>路经点</strong>并自动连线；按 <code>Enter</code> 结束当前路径。</p><ul><li>选中一条边，中点出现临时点，点击可在中间<strong>插入路经点</strong>（边分裂为两条）</li><li>贝塞尔边显示两个控制点手柄，拖拽调整弧形</li><li>拖拽路经点支持<strong>吸附</strong>：靠近其他节点时自动吸附对齐；吸附到另一个路经点则二者合并</li></ul><h3 id="绘制区域" tabindex="-1">绘制区域 <a class="header-anchor" href="#绘制区域" aria-label="Permalink to &quot;绘制区域&quot;">​</a></h3><p>支持多边形区域（依次点击顶点，<code>Enter</code> 闭合）和圆形区域（点击圆心，再点击确定半径），选中后可整体拖动或调整顶点/半径。</p><h2 id="路网录制" tabindex="-1">路网录制 <a class="header-anchor" href="#路网录制" aria-label="Permalink to &quot;路网录制&quot;">​</a></h2><p>手动逐点绘制效率低时，用<strong>录制</strong>方式生成路网：遥控设备实际走一遍，轨迹自动简化为节点和边，并入路网草稿。</p><ol><li>点击「录制」，选择站点内的在线设备</li><li>设备切换到手动模式，页面出现 FPV 面板和摇杆——遥控行驶一遍目标路径</li><li>行驶完成后点击「停止并生成草稿」，轨迹简化后并入当前路网</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>在世界地图上录制时，请确保设备处于 <strong>RTK 固定解</strong>状态，否则轨迹精度不足。</p></div><h2 id="从已有地图继承" tabindex="-1">从已有地图继承 <a class="header-anchor" href="#从已有地图继承" aria-label="Permalink to &quot;从已有地图继承&quot;">​</a></h2><p>地图更新（如重新建图）后，旧路网可以通过<strong>继承</strong>迁移到新地图：</p><ol><li>在新地图上放置<strong>至少 2 个节点</strong>作为锚点（位置与旧地图上对应）</li><li>点击「继承」，选择来源地图</li><li>平台自动配对锚点并对齐旧路网，叠加显示在当前地图上供确认</li><li>对照叠加效果确认无误后合并；不匹配的锚点可手动微调</li></ol><p><img src="'+l+'" alt=""></p>',27)])])}const b=r(s,[["render",n]]);export{m as __pageData,b as default};
